export function eotFromText(model, text, { source = "text", toEot, parseConllu } = {}) {
  if (typeof toEot !== "function" || typeof parseConllu !== "function") throw new TypeError("eotFromText: pass { toEot, parseConllu } from kernel/eot-rich.js");
