    edit(call, member) { return [{ start: member.property.start, end: member.property.end, to: "cas" }, { start: call.arguments[0].end, end: call.arguments[0].end, to: ", undefined" }]; },
    applies: (call) => call.arguments.length === 2,
  },
];

