  const re = new RegExp("(?<![\\p{L}\\p{N}])(\\p{Lu}[\\p{L}\\p{N}.'’-]*(?:[ \\t]+(?:\\p{Lu}[\\p{L}\\p{N}.'’-]*|" + PARTICLE + "))*)", "gu");
