const fs=require("fs"),path=require("path");
const builtins=new Set(require("module").builtinModules);
function scan(entry){
  const seen=new Map(),q=[entry],hits=[],dyn=[],proc=[];
  while(q.length){const rel=q.shift();if(seen.has(rel))continue;
    const abs=path.join(".",rel);
    if(!fs.existsSync(abs)){seen.set(rel,"MISSING");continue;}
    const t=fs.readFileSync(abs,"utf8");seen.set(rel,"ok");
    // robust: any from "x" / import "x" / export ... from "x", multi-line
    const specs=[...t.matchAll(/(?:\bimport|\bexport)\b[^;]*?\bfrom\s*["\x27]([^"\x27]+)["\x27]/gs)].map(m=>m[1]);
    for(const m of t.matchAll(/(?:^|\n)\s*import\s*["\x27]([^"\x27]+)["\x27]/g))specs.push(m[1]);
    for(const m of t.matchAll(/\bimport\(\s*["\x27]([^"\x27]+)["\x27]/g)){dyn.push([rel,m[1]]);}
    if(/\brequire\(|createRequire/.test(t))hits.push([rel,"require"]);
    if(/\bprocess\.|\bBuffer\b/.test(t.replace(/\/\/.*$/gm,"")))proc.push(rel);
    for(const s of specs){
      if(s.startsWith("node:")||builtins.has(s)){hits.push([rel,s]);continue;}
      if(s.startsWith(".")){q.push(path.posix.normalize(path.posix.join(path.posix.dirname(rel),s)));}
    }
  }
  return {files:[...seen.keys()],hits,dyn,proc};
}
