  /\bEveryone is entitled to\s+([^.;]+)/giu,
  /\bAll (?:human beings|are) equal (?:before|in)\s+([^.;]+)/giu,
  /\b(?:education|higher education|professional education|elementary education) shall be\s+([^.;]+)/giu,
  /\beveryone shall have the right to\s+([^.;]+)/giu,
