  try { if (lemmatizer && lemmatizer.lemma) lemma = lemmatizer.lemma(head) || head; } catch { /* keep the form */ }
  return { lemma, upos, feats: upos === 'VERB' ? 'VerbForm=Fin|Number=Sing|Person=3|Tense=Pres' : 'Number=Sing', head };
}


