  "spider": T("Spider"), "spiders": T("Spider"), "world war 2": T("World War II"), "capital": T("Capital city"),
};
export async function go(name, { ask, titles = {}, pages, leads = {}, wide = [], now = { year: 2026 }, quiet = false }) {
  const asked = { titles: [], leads: [] };
  const tt = { ...BASE_TITLES, ...titles };
  const deps = {
    fw: FW,
    resolveTitles: async (c) => { asked.titles.push(c.slice()); return new Map(c.map((x) => [x, tt[caseless(x)] ?? null])); },
    fetchLead: async (q) => { asked.leads.push(q); return leads[caseless(q)] ?? null; },
    searchPassages: async () => wide,
  };
  const passages = pages.map((p, i) => ({ ref: "S" + (i + 1), title: p.title, url: p.url || "https://en.wikipedia.org/wiki/" + p.title.replace(/ /g, "_"), host: "en.wikipedia.org", lang: "en", text: p.text }));
  const turn = await runAnswerTurn({ question: ask, lang: "en", passages, now, deps });
  console.log("\n=== " + name + " :: " + ask);
  if (turn.handoff) { console.log("HANDOFF", JSON.stringify(turn.handoff)); return turn; }
  if (turn.answer) console.log("ANSWER:", JSON.stringify(turn.answer.text), "| standing:", turn.answer.standing, "| filler:", turn.answer.filler.text, "\n  survived:", JSON.stringify(turn.answer.survived), "\n  unmeasured:", JSON.stringify(turn.answer.unmeasured.map((s) => s.split(":")[0])), "\n  row:", turn.answer.row.sentence.slice(0, 160));
  if (turn.contest && turn.contest.length) console.log("CONTEST:", turn.contest.map((r) => (r.filler && r.filler.text) + " <- " + r.sentence.slice(0, 120)));
  if (turn.gap) console.log("GAP:", turn.gap.kind, turn.gap.closest ? "closest=" + turn.gap.closest.sentence.slice(0, 140) : "");
  console.log("leads asked:", JSON.stringify(asked.leads), "| searched:", JSON.stringify(turn.searched));
